def rule(g):
    out=[]
    for br in range(0,12,3):
        row=[]
        for bc in range(0,12,3):
            cols={}
            for i in range(br,br+3):
                for j in range(bc,bc+3):
                    if g[i][j]!=5: cols[g[i][j]]=cols.get(g[i][j],0)+1
            if len(cols)==1: row.append(list(cols)[0])
            elif not cols: row.append(None)
            else: row.append(('CONFLICT',cols))
        out.append(row)
    return out
